import{z as n,x as r,o,c as B,q as t,j as i,D as e,d,s as E,S as l}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"活跃变量与数据流","description":"","frontmatter":{"title":"活跃变量与数据流","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dataflow-liveness.md","filePath":"cs/dataflow-liveness.md","lastUpdated":1791063341000}'),A={name:"cs/dataflow-liveness.md"};function c(p,a,u,_,h,f){const s=r("Mermaid");return o(),B("div",null,[a[2]||(a[2]=t('<h1 id="活跃变量与数据流" tabindex="-1">活跃变量与数据流 <a class="header-anchor" href="#活跃变量与数据流" aria-label="Permalink to &quot;活跃变量与数据流&quot;">​</a></h1><div class="epigraph"><p>变量在某点活跃，当存在从该点出发的路径会在重写前读它；这是向后的数据流。</p><footer>—— 据龙书第 8、9 章整理</footer></div><p>上一课<a href="/cs/dominator-phi">支配与 φ</a>让标量定值唯一，但寄存器分配仍要知道<strong>区间是否重叠</strong>。本课不重插 φ。缺口是：一般数据流框架，并以活跃变量为实例——后向、并汇合。指令选择还没开始；本课的对象仍是 IR 名字。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>临时太多，物理寄存器少。若两名字同时活跃，它们冲突，不能占同一寄存器。缺口是计算每条指令处的 <code>in/out</code> 活跃集。方程：<code>out[B]=\\bigcup_{后继} in[S]</code>，<code>in[B]=use[B]\\cup(out[B]-def[B])</code>。迭代到不动点。CFG 有环，故要迭代，不像 DAG 上一次 DP。</p><p>SSA 上活跃仍可算，区间更干净。本课方程对非 SSA 也成立，覆盖更广。</p><p><span class="marginnote">「向后」可以想成倒着读剧本：先看结尾谁出场，再一页页往回翻，记下每个角色从哪一刻起还有戏。变量也一样——从出口往回推，它最后一次被读的位置就是活跃区间的终点，中途被覆盖前没人读就是死赋值。</span></p><h3 id="数据流不是「再跑一遍-bfs」" tabindex="-1">数据流不是「再跑一遍 BFS」 <a class="header-anchor" href="#数据流不是「再跑一遍-bfs」" aria-label="Permalink to &quot;数据流不是「再跑一遍 BFS」&quot;">​</a></h3><p>BFS 求无权距离；数据流是格上的不动点：子集格、并或交、单调函数。到达定值向前；可用表达式另一套 gen/kill。本课用活跃代表后向，不把所有分析写成词条。</p><p><span class="marginnote">龙书第 9 章数据流框架：单调性保证从空或全开始迭代收敛。Kildall 早期工作点名即可。寄存器分配下一课用冲突图吃本课的活跃。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对每个基本块算 <code>use</code>/<code>def</code>。倒序或轮询块，更新 <code>in/out</code> 直至不变。指令级可再细拆。复杂度多项式：集的大小 \\(\\times\\) 块数 \\(\\times\\) 迭代（深度相关）。</p>',12)),(o(),i(l,null,{default:e(()=>[E(s,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20CFG%5B%22CFG%22%5D%20--%3E%20UK%5B%22use%20%2F%20def%22%5D%0A%20%20UK%20--%3E%20FP%5B%22%E8%BF%AD%E4%BB%A3%20in%2Fout%22%5D%0A%20%20FP%20--%3E%20LIVE%5B%22%E5%90%84%E7%82%B9%E6%B4%BB%E8%B7%83%E9%9B%86%22%5D%0A%20%20LIVE%20--%3E%20IG%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%86%B2%E7%AA%81%E5%9B%BE%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<p><a href="/cs/loop-invariant">循环不变式</a>分析正确性；这里的不变式是「当前解低估或高估活跃」，单调逼近不动点。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>死赋值：<code>def</code> 的名字不在 <code>out</code> 则可删（无副作用）。下一课冲突图：边连接同时活跃的名字。<a href="/cs/npc-canonical">NPC</a> 课已说着色难；本课只供图。SSA 的 φ 在块首：活跃从后继回传时要按前驱拆，实现细节点名。</p><p>后向传播在一个三行块里怎么走：</p>',4)),(o(),i(l,null,{default:e(()=>[E(s,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20I3%5B%22I3%3A%20return%20x%20%E2%80%94%E2%80%94%20%E5%87%BA%E5%8F%A3%E5%A4%84%E6%B4%BB%E8%B7%83%E7%9A%84%E6%98%AF%20x%22%5D%20--%3E%20I2%5B%22I2%3A%20x%20%3D%205%20%E2%80%94%E2%80%94%20%E8%87%AA%E5%B7%B1%E7%9A%84%20def%20%E6%8A%B5%E6%B6%88%20out%20%E9%87%8C%E7%9A%84%20x%EF%BC%8Cin%20%E5%8F%98%E7%A9%BA%22%5D%0A%20%20I2%20--%3E%20I1%5B%22I1%3A%20x%20%3D%20a%20%2B%20b%20%E2%80%94%E2%80%94%20def%20%E7%9A%84%20x%20%E5%9C%A8%E8%A2%AB%E8%A6%86%E7%9B%96%E5%89%8D%E6%97%A0%E4%BA%BA%E8%AF%BB%EF%BC%8C%E6%95%B4%E6%9D%A1%E6%98%AF%E6%AD%BB%E8%B5%8B%E5%80%BC%22%5D%0A%20%20I1%20--%3E%20R%5B%22in%20%3D%20a%20%E4%B8%8E%20b%EF%BC%9A%E7%9C%9F%E6%AD%A3%E9%9C%80%E8%A6%81%E6%B4%BB%E8%BF%87%E8%BF%99%E6%AE%B5%E7%9A%84%E5%8F%AA%E6%9C%89%E5%AE%83%E4%BB%AC%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[d(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<p><span class="marginnote">数字感受冲突图的规模：2 个临时变量同时活跃最多 1 条冲突边，3 个最多 3 条，8 个最多 28 条——边数按平方涨。寄存器只有十几个，活跃变量一多，着色必然溢出到栈，这就是本课分析要压短活跃区间的动机。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不着色、不选指令、不做别名分析（指针使 <code>use</code> 不精确，保守当全活跃）。常量传播是另一套格。后课默认：能算出 IR 名字的活跃。指令选择把 IR 运算变成机器指令模板。</p><p><span class="marginnote">初学者容易以为有指针时活跃分析会「算错」。实际做法是保守化：只要指针可能碰到某个名字，就当它一直活跃——宁可多留几个寄存器，也绝不错删一条其实有用的赋值。分析宁可高估，不冒险。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>活跃 = 向后数据流；<code>use</code>/<code>def</code> 迭代到不动点。</li><li>同时活跃 ⇒ 寄存器冲突。</li><li>框架可换到达定值等；本课只钉活跃。</li><li>出处：Aho et al., 龙书第 8–9 章。</li></ul>',6))])}const C=n(A,[["render",c]]);export{D as __pageData,C as default};
